假设以带头结点的循环链表表示队列，并且只设一个指针指向队尾元素结点（注意不设头指针
）
，试
编写相应的队列初始化、入队列何处队列的算法。
解：
typedef
int
ElemType;
typedef
struct
NodeType{
ElemType
data;
NodeType
*next;
}QNode,*QPtr;
typedef
struct{
QPtr
rear;
int
size;
}Queue;
Status
InitQueue(Queue&
q)
{
q.rear=NULL;
q.size=0;
return
OK;
}
Status
EnQueue(Queue&
q,ElemType
e)
{
QPtr
p;
p=new
QNode;
if(!p)
return
FALSE;
p->data=e;
if(!q.rear){
q.rear=p;
p->next=q.rear;
}
else{
p->next=q.rear->next;
q.rear->next=p;
q.rear=p;
}
q.size++;
return
OK;
